// AUTO-GENERATED by scripts/build-r-helpers.ts from rhelpers/*.R.
// Do not edit. Edit the .R sources and run `pnpm gen:rhelpers`.

/**
 * The inline R helper definitions the exporter can emit, keyed by the name a
 * mark requests one by. A script carries only the helpers it references, so a
 * reader gets plain rtracklayer and ggplot2 they can edit in place.
 */
export const HELPERS: Record<string, string> = {
  bind_groups: "# rbind the frames a split produced, or a frame with 'columns' and no rows where\n# it produced none: do.call(rbind, list()) is NULL, and a NULL frame fails every\n# step and layer after it, where an empty window is a state the browser draws\n# as an empty panel.\nbind_groups <- function(parts, columns) {\n  out <- do.call(rbind, parts)\n  if (is.null(out)) {\n    out <- data.frame(setNames(rep(list(logical(0)), length(columns)), columns),\n                      check.names = FALSE)\n  }\n  out\n}",
  category_values: "# The palette entry each categorical value takes, by the browser's rule: a\n# non-negative integer takes the slot it names anchored at 1, anything else\n# hashes in (hashString: 31 * h + code unit, as a signed 32-bit integer). A\n# value in 'listed' (a named vector) keeps the entry listed for it. Answers a\n# vector named by value, for scale_*_manual(values = ).\ncategory_values <- function(values, palette, listed = NULL) {\n  hash <- function(s) {\n    h <- 0\n    for (ch in utf8ToInt(s)) h <- (h * 31 + ch) %% 4294967296\n    abs(if (h >= 2147483648) h - 4294967296 else h)\n  }\n  slot <- function(v) {\n    num <- if (nzchar(v) && !nzchar(trimws(v))) 0 else suppressWarnings(as.numeric(v))\n    if (nzchar(v) && is.finite(num) && num == floor(num) && num >= 0)\n      (num + length(palette) - 1) %% length(palette)\n    else hash(v) %% length(palette)\n  }\n  values <- unique(as.character(values[!is.na(values)]))\n  out <- palette[vapply(values, slot, numeric(1)) + 1]\n  names(out) <- values\n  c(listed, out[setdiff(values, names(listed))])\n}",
  file_refname: "# The name a file spells a contig with, where the assembly's alias for it\n# differs from the view's name; a contig with no alias keeps its own name.\nfile_refname <- function(chrom, aliases) {\n  if (chrom %in% names(aliases)) aliases[[chrom]] else chrom\n}",
  jbrowse_regions: "# Read each region with read(chrom, start, end), a ggjbrowse result, and bind\n# the results into one on the cumulative axis region_layout() defines, which\n# the result's geoms draw end to end. A table's start, end and position move\n# by their region's offset and each row gains '.region'; a span is cut to its\n# region and a mark outside it dropped, so nothing draws over the gap into the\n# next region. A read, feature, subfeature or variant number indexes the\n# bound table, and a line's run stays its own. A key lists each entry once,\n# the score domain spans every region's, and the region is the whole axis.\njbrowse_regions <- function(regions, read) {\n  parts <- lapply(seq_len(nrow(regions)), function(i)\n    read(regions$chrom[i], regions$start[i], regions$end[i]))\n  if (length(parts) == 1) return(parts[[1]])\n  indexes <- c(read = \"reads\", feature = \"features\",\n    subfeature = \"subfeatures\", variant = \"variants\")\n  listing <- c(\"legend\", \"arc_legend\", \"sections\", \"sources\", \"rows\", \"rules\")\n  counts <- setNames(numeric(length(indexes) + 1), c(indexes, \"run\"))\n  for (i in seq_along(parts)) {\n    lo <- regions$start[i]; hi <- regions$end[i]\n    shift <- regions$offset[i] - lo\n    x <- parts[[i]]\n    for (name in setdiff(names(x), listing)) {\n      d <- x[[name]]\n      if (!is.data.frame(d)) next\n      if (!is.null(d$start)) {\n        d <- d[d$end > lo & d$start < hi, , drop = FALSE]\n        d$start <- pmax(d$start, lo) + shift\n        d$end <- pmin(d$end, hi) + shift\n      }\n      if (!is.null(d$position)) {\n        d <- d[d$position >= lo & d$position < hi, , drop = FALSE]\n        d$position <- d$position + shift\n      }\n      for (column in intersect(names(indexes), names(d))) {\n        d[[column]] <- d[[column]] + counts[[indexes[[column]]]]\n      }\n      if (!is.null(d$run)) d$run <- d$run + counts[[\"run\"]]\n      d$.region <- rep(i, nrow(d))\n      x[[name]] <- d\n    }\n    for (table in intersect(indexes, names(x))) {\n      counts[[table]] <- counts[[table]] + nrow(parts[[i]][[table]])\n    }\n    counts[[\"run\"]] <- counts[[\"run\"]] + max(c(0, parts[[i]]$marks$run))\n    parts[[i]] <- x\n  }\n  bound <- function(pick) {\n    first <- pick(parts[[1]])\n    d <- do.call(rbind, lapply(parts, pick))\n    rownames(d) <- NULL\n    for (a in setdiff(names(attributes(first)), c(\"names\", \"row.names\", \"class\")))\n      attr(d, a) <- attr(first, a)\n    d\n  }\n  out <- parts[[1]]\n  for (name in names(out)) {\n    if (is.data.frame(out[[name]]) && !name %in% listing[-(1:2)]) {\n      out[[name]] <- bound(function(x) x[[name]])\n      if (name %in% listing) out[[name]] <- unique(out[[name]])\n    }\n  }\n  for (key in names(out$keys)) {\n    out$keys[[key]] <- unique(bound(function(x) x$keys[[key]]))\n  }\n  if (!is.null(out$domain)) out$domain <- range(lapply(parts, `[[`, \"domain\"))\n  if (!is.null(out$height)) out$height <- max(sapply(parts, `[[`, \"height\"))\n  out$region <- list(chrom = \"\", start = min(regions$cum_start),\n    end = max(regions$cum_end))\n  out\n}",
  read_bam: "# Read the alignments overlapping a region into data.frame(start, end, strand,\n# name, score, flags, cigar, template_length, pair_orientation, next_ref,\n# next_pos, refName, read_index), the fields a JBrowse read answers to under the same\n# names, plus each read's position in readGAlignments order, which a per-read\n# overlay such as bam_mismatches joins on: start is 0-based\n# half-open over the reference span the CIGAR covers, strand is 1 or -1, score\n# is MAPQ with 255 (unavailable) as NA, template_length is signed TLEN, and\n# pair_orientation is the F1R2-style code, NA unless both mates map to one\n# contig. One tags.<TAG> column per name in 'tags', numeric where every value\n# parses as a number. Unmapped reads are not returned, and a contig the index\n# lacks reads as no reads.\nread_bam <- function(uri, chrom, start, end, tags = character(0), index = uri) {\n  bf <- BamFile(uri, index = index)\n  known <- chrom %in% seqlevels(bf)\n  which <- if (known) GRanges(chrom, IRanges(start + 1, end))\n    else GRanges(seqlevels(bf)[1], IRanges(1, 1))\n  ga <- readGAlignments(bf, param = ScanBamParam(which = which, tag = tags,\n    what = c(\"qname\", \"flag\", \"mapq\", \"isize\", \"mrnm\", \"mpos\")))\n  if (!known) ga <- ga[0]\n  m <- mcols(ga)\n  flag <- m$flag\n  bit <- function(f) bitwAnd(flag, f) != 0\n  paired <- bit(0x1L)\n  mate_chrom <- as.character(m$mrnm)\n  oriented <- paired & !bit(0x4L) & !bit(0x8L) & !is.na(mate_chrom) & mate_chrom == chrom\n  self_left <- ifelse(start(ga) != m$mpos, start(ga) < m$mpos, bit(0x40L))\n  self <- paste0(ifelse(bit(0x10L), \"R\", \"F\"), ifelse(bit(0x40L), \"1\", \"2\"))\n  mate <- paste0(ifelse(bit(0x20L), \"R\", \"F\"), ifelse(bit(0x40L), \"2\", \"1\"))\n  df <- data.frame(start = start(ga) - 1L, end = end(ga),\n    strand = ifelse(as.character(strand(ga)) == \"-\", -1L, 1L),\n    name = m$qname, score = ifelse(m$mapq == 255L, NA_integer_, m$mapq),\n    flags = flag, cigar = cigar(ga), template_length = m$isize,\n    pair_orientation = ifelse(oriented,\n      ifelse(self_left, paste0(self, mate), paste0(mate, self)), NA_character_),\n    next_ref = ifelse(paired, mate_chrom, NA_character_),\n    next_pos = ifelse(paired & !is.na(m$mpos), m$mpos - 1L, NA_integer_),\n    refName = rep(chrom, length(ga)), read_index = seq_along(ga),\n    stringsAsFactors = FALSE, check.names = FALSE)\n  for (t in tags) df[[paste0(\"tags.\", t)]] <- utils::type.convert(\n    if (is.null(m[[t]])) rep(NA_character_, length(ga)) else as.character(m[[t]]),\n    as.is = TRUE)\n  df\n}",
  read_bed: "# Read the BED records in a region through the file's tabix index into a\n# data.frame(start, end, strand, name, score, thick_start, thick_end,\n# block_starts, block_sizes, item_rgb), one row per record: start is 0-based\n# half-open, strand 1, -1 or 0, and the block columns are BED12's comma lists,\n# block starts relative to the record's start, NA on a record without blocks.\n# item_rgb is the record's own color, NA where it is 0, as UCSC reads it. A\n# contig the index lacks reads as no records, as the browser draws it.\nread_bed <- function(uri, chrom, start, end, index = paste0(uri, \".tbi\")) {\n  tf <- TabixFile(uri, index = index)\n  g <- if (!chrom %in% seqnamesTabix(tf)) GRanges() else\n    import(tf, which = GRanges(chrom, IRanges(start + 1, end)), format = \"bed\")\n  m <- mcols(g)\n  n <- length(g)\n  na <- rep(NA_character_, n)\n  thick <- if (is.null(m$thick)) NULL else m$thick\n  blocks <- if (is.null(m$blocks)) NULL else m$blocks\n  data.frame(\n    start = start(g) - 1L, end = end(g),\n    strand = unname(c(\"+\" = 1L, \"-\" = -1L, \"*\" = 0L)[as.character(strand(g))]),\n    name = if (is.null(m$name)) na else as.character(m$name),\n    score = if (is.null(m$score)) rep(NA_real_, n) else as.numeric(m$score),\n    thick_start = if (is.null(thick)) rep(NA_integer_, n) else start(thick) - 1L,\n    thick_end = if (is.null(thick)) rep(NA_integer_, n) else end(thick),\n    block_starts = if (is.null(blocks)) na else\n      vapply(blocks, function(b) paste(start(b) - 1L, collapse = \",\"), \"\"),\n    block_sizes = if (is.null(blocks)) na else\n      vapply(blocks, function(b) paste(width(b), collapse = \",\"), \"\"),\n    item_rgb = if (is.null(m$itemRgb)) na else\n      ifelse(m$itemRgb %in% \"#000000\", NA_character_, as.character(m$itemRgb)),\n    stringsAsFactors = FALSE)\n}",
  read_bigbed: "# Read the BigBed records in a region into read_bed()'s data.frame(start, end,\n# strand, name, score, thick_start, thick_end, block_starts, block_sizes,\n# item_rgb), plus\n# one column per name in 'fields', the file's autoSql columns the display\n# reads, numeric where every value parses as a number. 'score_column' names\n# the column the adapter reads score from. A contig the file lacks reads as no\n# records, as the browser draws it.\n#\n# rtracklayer's BigBed reader fails on any list column, which every BED12\n# bigBed has, so this walks the file itself: the chromosome B+ tree to the\n# contig's id, the R-tree to the data blocks that overlap, then the\n# zlib-compressed records. A URL is read in HTTP ranges.\nread_bigbed <- function(uri, chrom, start, end, fields = character(0), score_column = NULL) {\n  whole <- NULL\n  fetch <- if (grepl(\"^[a-z]+://\", uri)) function(off, n) {\n    if (is.null(whole)) {\n      h <- curl::new_handle(range = sprintf(\"%.0f-%.0f\", off, off + n - 1))\n      r <- curl::curl_fetch_memory(uri, handle = h)\n      if (r$status_code == 206) return(r$content)\n      # A server that ignores the range sends the whole file once.\n      whole <<- r$content\n    }\n    whole[seq.int(off + 1, min(length(whole), off + n))]\n  } else function(off, n) {\n    con <- file(uri, \"rb\"); on.exit(close(con))\n    seek(con, off); readBin(con, \"raw\", n)\n  }\n  en <- \"little\"\n  u32 <- function(b, p) {\n    v <- readBin(b[p:(p + 3)], \"integer\", 1, 4, endian = en)\n    if (v < 0) v + 2^32 else v\n  }\n  u16 <- function(b, p) readBin(b[p:(p + 1)], \"integer\", 1, 2, signed = FALSE, endian = en)\n  u64 <- function(b, p) if (en == \"little\") u32(b, p) + u32(b, p + 4) * 2^32 else\n    u32(b, p) * 2^32 + u32(b, p + 4)\n\n  h <- fetch(0, 64)\n  if (u32(h, 1) != 0x8789F2EB) en <- \"big\"\n  if (u32(h, 1) != 0x8789F2EB) stop(uri, \" is not a BigBed file\")\n  chrom_tree <- u64(h, 9); index <- u64(h, 25)\n  defined <- u16(h, 35); sql_at <- u64(h, 37); compressed <- u32(h, 53) > 0\n\n  sql <- fetch(sql_at, 65536)\n  sql <- rawToChar(sql[seq_len(match(as.raw(0), sql, length(sql) + 1) - 1)])\n  names <- regmatches(sql, gregexpr(\"[A-Za-z_][A-Za-z0-9_]*(?=\\\\s*;)\", sql, perl = TRUE))[[1]]\n\n  # The B+ tree's keys are the names null-padded to keySize and sorted bytewise.\n  t <- fetch(chrom_tree, 32)\n  block <- u32(t, 5); key_size <- u32(t, 9)\n  target <- charToRaw(chrom)\n  cid <- if (length(target) > key_size) NA else {\n    target <- c(target, raw(key_size - length(target)))\n    le <- function(a) { d <- which(a != target)[1]; is.na(d) || a[d] < target[d] }\n    node <- chrom_tree + 32; found <- NA\n    repeat {\n      b <- fetch(node, 4 + block * (key_size + 8))\n      n <- u16(b, 3); at <- 4 + (seq_len(n) - 1) * (key_size + 8)\n      keys <- lapply(at, function(p) b[p + seq_len(key_size)])\n      if (b[1] == 1) {\n        hit <- which(vapply(keys, function(k) all(k == target), TRUE))\n        if (length(hit)) found <- u32(b, at[hit[1]] + key_size + 1)\n        break\n      }\n      below <- which(vapply(keys, le, TRUE))\n      if (!length(below)) break\n      node <- u64(b, at[max(below)] + key_size + 1)\n    }\n    found\n  }\n\n  # Overlap compares (chromIx, base) pairs, since a leaf can span contigs.\n  index_block <- u32(fetch(index, 48), 5)\n  blocks <- list()\n  walk <- function(node) {\n    b <- fetch(node, 4 + index_block * 32)\n    leaf <- b[1] == 1; n <- u16(b, 3); size <- if (leaf) 32 else 24\n    for (i in seq_len(n)) {\n      p <- 5 + (i - 1) * size\n      sc <- u32(b, p); sb <- u32(b, p + 4); ec <- u32(b, p + 8); eb <- u32(b, p + 12)\n      if ((sc < cid || (sc == cid && sb < end)) && (ec > cid || (ec == cid && eb > start))) {\n        if (leaf) blocks[[length(blocks) + 1]] <<- c(u64(b, p + 16), u64(b, p + 24))\n        else walk(u64(b, p + 16))\n      }\n    }\n  }\n  if (!is.na(cid)) walk(index + 48)\n\n  rows <- list()\n  for (bl in blocks) {\n    b <- fetch(bl[1], bl[2])\n    if (compressed) b <- memDecompress(b, \"gzip\")\n    nul <- which(b == as.raw(0)); p <- 1\n    while (p + 12 <= length(b)) {\n      z <- nul[findInterval(p + 11, nul) + 1]\n      if (is.na(z)) break\n      if (u32(b, p) == cid) {\n        s <- u32(b, p + 4); e <- u32(b, p + 8)\n        if (s < end && e > start) rows[[length(rows) + 1]] <-\n          list(s, e, if (z > p + 12) rawToChar(b[(p + 12):(z - 1)]) else \"\")\n      }\n      p <- z + 1\n    }\n  }\n\n  rest <- lapply(rows, function(r) strsplit(r[[3]], \"\\t\", fixed = TRUE)[[1]])\n  col <- function(i) vapply(rest, function(r) if (length(r) >= i) r[[i]] else NA_character_, \"\")\n  bed <- function(i, f) if (defined >= i + 3) f(col(i)) else f(rep(NA_character_, length(rows)))\n  num <- function(v) suppressWarnings(as.numeric(v))\n  list_col <- function(v) sub(\",$\", \"\", v)\n  rgb_col <- function(v) {\n    t <- regmatches(v, regexec(\"^\\\\s*(\\\\d+),(\\\\d+),(\\\\d+)\\\\s*$\", v))\n    vapply(t, function(m) if (length(m) == 4 && all(as.integer(m[2:4]) <= 255) &&\n      any(as.integer(m[2:4]) > 0)) grDevices::rgb(as.integer(m[2]), as.integer(m[3]),\n      as.integer(m[4]), maxColorValue = 255) else NA_character_, \"\")\n  }\n  df <- data.frame(\n    start = vapply(rows, function(r) as.integer(r[[1]]), 0L),\n    end = vapply(rows, function(r) as.integer(r[[2]]), 0L),\n    strand = bed(3, function(v) ifelse(v %in% \"+\", 1L, ifelse(v %in% \"-\", -1L, 0L))),\n    name = bed(1, identity), score = bed(2, num),\n    thick_start = bed(4, num), thick_end = bed(5, num),\n    block_starts = bed(9, list_col), block_sizes = bed(8, list_col),\n    item_rgb = bed(6, rgb_col),\n    stringsAsFactors = FALSE)\n  named <- function(f) {\n    i <- match(f, names) - 3\n    if (is.na(i) || i < 1) rep(NA_character_, nrow(df)) else col(i)\n  }\n  if (!is.null(score_column)) df$score <- num(named(score_column))\n  for (f in fields) df[[f]] <- utils::type.convert(named(f), as.is = TRUE)\n  df\n}",
  read_bigwig: "# Read a BigWig region into data.frame(seqnames, start, end, score), start\n# 0-based half-open like every reader here (rtracklayer answers 1-based\n# inclusive, which leaves a 1bp hole between adjacent bins). Opened as a\n# BigWigFile so a URL whose query hides the extension still reads.\nread_bigwig <- function(uri, chrom, start, end) {\n  gr <- rtracklayer::import(rtracklayer::BigWigFile(uri),\n                            which = GRanges(chrom, IRanges(start + 1, end)))\n  df <- as.data.frame(gr)\n  df$start <- df$start - 1L\n  df\n}",
  read_gff: "# Read the GFF3 features in a region through the file's tabix index into a\n# data.frame(start, end, strand, type, source, score, phase, id, parent, name),\n# plus one column per name in 'attrs', the column-9 attributes the display\n# reads: matched without regard to case, as JBrowse matches them; numeric where\n# every value parses as a number, as a channel reads it; all NA where the file\n# lacks the attribute. start is 0-based half-open, and strand is 1, -1 or 0, the\n# values a config's strand domain names. A contig the index lacks reads as no\n# features, as the browser draws it.\nread_gff <- function(uri, chrom, start, end, attrs = character(0), index = paste0(uri, \".tbi\")) {\n  tf <- TabixFile(uri, index = index)\n  g <- if (!chrom %in% seqnamesTabix(tf)) GRanges() else withCallingHandlers(\n    import(tf, which = GRanges(chrom, IRanges(start + 1, end)), format = \"gff3\"),\n    # rtracklayer rewinds the connection it opened itself and warns about it\n    warning = function(w) if (grepl(\"rewinding\", conditionMessage(w))) invokeRestart(\"muffleWarning\"))\n  m <- mcols(g)\n  # A GFF attribute can hold a comma list, which rtracklayer surfaces as a\n  # CharacterList - and as.character() on one errors rather than flattening, so\n  # join it back to the spelling the file used.\n  col <- function(nm) {\n    hit <- match(tolower(nm), tolower(names(m)))\n    v <- if (is.na(hit)) NULL else m[[hit]]\n    if (is.null(v)) rep(NA_character_, length(g))\n    else if (methods::is(v, \"List\")) vapply(v, function(x)\n      if (length(x)) paste(as.character(x), collapse = \",\") else NA_character_,\n      character(1))\n    else as.character(v)\n  }\n  # A row with several parents (an exon two isoforms share) is a child of each.\n  parents <- if (is.null(m$Parent)) as.list(rep(NA_character_, length(g))) else\n    lapply(m$Parent, function(v) if (length(v)) as.character(v) else NA_character_)\n  each <- rep(seq_along(g), lengths(parents))\n  df <- data.frame(start = start(g) - 1L, end = end(g), strand = unname(c(\"+\" = 1L, \"-\" = -1L, \"*\" = 0L)[as.character(strand(g))]),\n             type = col(\"type\"), source = col(\"source\"),\n             score = suppressWarnings(as.numeric(col(\"score\"))),\n             phase = suppressWarnings(as.integer(col(\"phase\"))),\n             id = col(\"ID\"), parent = rep(NA_character_, length(g)), name = col(\"Name\"),\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (a in attrs) df[[a]] <- utils::type.convert(col(a), as.is = TRUE)\n  df <- df[each, , drop = FALSE]\n  df$parent <- unlist(parents)\n  rownames(df) <- NULL\n  df\n}",
  read_regions: "# Read one data.frame per region with reader(chrom, start, end), shift the\n# columns 'coords' names onto the cumulative-bp axis region_layout() defines and\n# rbind the frames into one, with a '.region' column, so a single ggplot panel\n# spans several discontiguous regions on one x-axis. 'reader' answers a\n# genomic-coordinate data.frame, with no rows for a region holding nothing; a\n# reader with a 'region' argument is also handed the region's row number, so\n# it can pick out what an earlier frame read there.\n# A feature is clipped to its region only where there is more than one: the\n# browser runs its transforms over the unclipped feature and clips the drawing,\n# which coord_cartesian() does for a lone region, while on a shared axis a\n# feature past its region's edge would draw over the gap into the next region.\nread_regions <- function(reader, regions, coords, clip = nrow(regions) > 1) {\n  parts <- lapply(seq_len(nrow(regions)), function(i) {\n    args <- list(regions$chrom[i], regions$start[i], regions$end[i])\n    if (\"region\" %in% names(formals(reader))) args$region <- i\n    df <- do.call(reader, args)\n    shift <- regions$offset[i] - regions$start[i]\n    for (col in coords) {\n      v <- df[[col]]\n      if (clip) v <- pmin(pmax(v, regions$start[i]), regions$end[i])\n      df[[col]] <- v + shift\n    }\n    df$.region <- rep(i, nrow(df))\n    df\n  })\n  do.call(rbind, parts)\n}",
  read_vcf: "# Read VCF records in a region via the tabix index (Rsamtools - no\n# VariantAnnotation needed) into data.frame(start, end, name, REF, ALT, QUAL,\n# FILTER, type), plus one INFO.<key> column per key in 'info', the INFO fields\n# the display reads - a flag key is TRUE where present and NA where not, and a\n# column every value of which parses as a number becomes numeric. SV span (END)\n# comes from INFO, and type is the browser's SO term from the alleles: SNV,\n# substitution, insertion, deletion, breakend, a symbolic alt's class, joined\n# across alts.\n# start is 0-based half-open (BED-style). A contig the index lacks reads as no\n# records, as the browser draws it.\nread_vcf <- function(uri, chrom, start, end, info = character(0), index = paste0(uri, \".tbi\")) {\n  info_field <- function(inf, key) {\n    pat <- paste0(\"(?:^|;)\", key, \"(?:=([^;]*))?(?:;|$)\")\n    vapply(inf, function(x) {\n      m <- regmatches(x, regexec(pat, x, perl = TRUE))[[1]]\n      if (!length(m)) NA_character_ else if (nzchar(m[2])) m[2] else \"TRUE\"\n    }, character(1), USE.NAMES = FALSE)\n  }\n  tf <- TabixFile(uri, index = index)\n  lines <- if (!chrom %in% seqnamesTabix(tf)) character(0) else\n    unlist(scanTabix(tf, param = GRanges(chrom, IRanges(start + 1, end))))\n  cols <- if (length(lines)) do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n          else matrix(character(), 0, 8)\n  pos <- as.integer(cols[, 2]); ref <- cols[, 4]\n  alt <- sub(\",.*\", \"\", cols[, 5]); inf <- cols[, 8]\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(info_field(inf, \"END\")))\n  symbolic_terms <- c(DEL = \"deletion\", INS = \"insertion\", DUP = \"duplication\",\n    INV = \"inversion\", INVDUP = \"inverted_duplication\",\n    CNV = \"copy_number_variation\", TRA = \"translocation\",\n    \"DUP:TANDEM\" = \"tandem_duplication\", NON_REF = \"sequence_variant\",\n    \"*\" = \"sequence_variant\")\n  so_term <- function(a, r) {\n    if (a == \".\") return(\"remark\")\n    if (startsWith(a, \"<\")) {\n      parts <- strsplit(substr(a, 2, nchar(a) - 1), \":\", fixed = TRUE)[[1]]\n      for (i in rev(seq_along(parts))) {\n        term <- paste(parts[seq_len(i)], collapse = \":\")\n        if (term %in% names(symbolic_terms)) return(symbolic_terms[[term]])\n        if (grepl(\"^CN[0-9]+$\", term)) return(\"copy_number_variation\")\n      }\n      return(\"variant\")\n    }\n    if (a == \"*\") return(\"sequence_variant\")\n    if (grepl(\"[][]\", a)) return(\"breakend\")\n    if (nchar(r) == 1 && nchar(a) == 1) \"SNV\"\n    else if (nchar(r) == nchar(a)) \"substitution\"\n    else if (nchar(r) < nchar(a)) \"insertion\"\n    else \"deletion\"\n  }\n  type <- as.character(unlist(Map(function(r, a) paste(unique(\n    vapply(strsplit(a, \",\", fixed = TRUE)[[1]], so_term, \"\", r = r)),\n    collapse = \",\"), ref, cols[, 5], USE.NAMES = FALSE)))\n  df <- data.frame(start = pos - 1L,\n             end = ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L),\n             name = ifelse(cols[, 3] == \".\", NA_character_, cols[, 3]),\n             REF = ref, ALT = alt,\n             QUAL = suppressWarnings(as.numeric(cols[, 6])),\n             FILTER = cols[, 7], type = type,\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (k in info) df[[paste0(\"INFO.\", k)]] <-\n    utils::type.convert(info_field(inf, k), as.is = TRUE)\n  df\n}",
  region_layout: "# Lay a set of displayed regions out on one continuous \"cumulative bp\" x-axis,\n# the way JBrowse concatenates several regions in a single linear view: each\n# region occupies a span proportional to its bp width, with a small gap between\n# them. 'regions' is a data.frame(chrom, start, end) (0-based half-open); this\n# adds offset (the region's left edge on the cumulative axis), width, gap, and\n# cum_start/cum_end. The first region is anchored at its own genomic start, so a\n# lone region keeps native genomic coordinates (a single-region figure is\n# unchanged). cum_pos for a position p in region i is offset[i] + (p - start[i]).\nregion_layout <- function(regions, gap_frac = 0.012) {\n  w <- regions$end - regions$start\n  gap <- max(1, round(sum(w) * gap_frac))\n  regions$offset <- regions$start[1] + head(cumsum(c(0, w + gap)), length(w))\n  regions$width <- w; regions$gap <- gap\n  regions$cum_start <- regions$offset; regions$cum_end <- regions$offset + w\n  regions\n}",
  step_path: "# The vertices of a step line through df, for geom_path(aes(.x, .y, group =\n# .group)): each row's value 'y' held from 'x' to 'x2', joined to the next row\n# where that one starts at this one's end, and dropped to 'origin' across a\n# gap, as the browser draws a line mark. The rows of one group, one value of\n# every column 'by' names, draw as one path in 'x' order. Each vertex carries\n# its row's columns, so a color mapped to one stays per span.\nstep_path <- function(df, x, x2, y, origin = 0, by = \".region\") {\n  n <- nrow(df)\n  df$.group <- if (n) interaction(lapply(df[by], addNA), drop = TRUE) else factor()\n  df <- df[order(df$.group, df[[x]]), , drop = FALSE]\n  abuts <- if (!n) logical(0) else\n    c(FALSE, df$.group[-1] == df$.group[-n] & df[[x]][-1] == df[[x2]][-n])\n  k <- rep(seq_len(n), each = 4)\n  corner <- rep(1:4, n)\n  out <- df[k, , drop = FALSE]\n  out$.x <- ifelse(corner <= 2, df[[x]][k], df[[x2]][k])\n  out$.y <- ifelse(corner == 2 | corner == 3, df[[y]][k], origin)\n  keep <- corner == 2 | corner == 3 |\n    (corner == 1 & !abuts[k]) | (corner == 4 & !c(abuts[-1], FALSE)[k])\n  out[keep, , drop = FALSE]\n}",
}
